(function () {{
    var adminT = pm.collectionVariables.get('adminToken');
    if (!adminT) {{
        pm.collectionVariables.set('adminToken', pm.collectionVariables.get('token') || '');
    }}
    var req = {{
        url: pm.collectionVariables.get('baseUrl') + '/api/auth/login',
        method: 'POST',
        header: {{ 'Content-Type': 'application/json' }},
        body: {{ mode: 'raw', raw: JSON.stringify({{
            username: pm.collectionVariables.get('usuarioVinculadoUsername'),
            senha: 'mudar123'
        }}) }}
    }};
    pm.sendRequest(req, function (err, res) {{
        if (err || res.code !== 200) {{ return; }}
        var j = res.json();
        pm.collectionVariables.set('token', j.token);
    }});
}})();
